import{_ as r,o as e,c as a,a2 as o}from"./chunks/framework.BZO4qERu.js";const u=JSON.parse('{"title":"Supermarket","description":"","frontmatter":{},"headers":[],"relativePath":"ru/guides/supermarket.md","filePath":"ru/guides/supermarket.md","lastUpdated":1792323081000}'),s={name:"ru/guides/supermarket.md"};function n(l,t,p,d,i,h){return e(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="supermarket" tabindex="-1">Supermarket <a class="header-anchor" href="#supermarket" aria-label="Permalink to &quot;Supermarket&quot;">​</a></h1><p>Supermarket — это встроенный каталог приложений Memoh. <strong>Приложение</strong> (App) здесь — упакованная единица возможностей: одно приложение может нести несколько <strong>навыков</strong> (переиспользуемых порядков действий), <strong>зависимостей</strong> (инструментов, устанавливаемых в рабочее пространство) и <strong>коннекторов</strong> (привязок к сторонним сервисам вроде GitHub или Notion). Приложение устанавливается целиком — не нужно отдельно разыскивать навыки или коннекторы.</p><p>Откройте <strong>Supermarket</strong> в боковой панели клиента: приложения разложены по категориям, их можно искать и фильтровать по тегам. На странице приложения показаны его описание, состав компонентов (сколько навыков, зависимостей и коннекторов), автор, версия, исходный реестр и ссылки.</p><hr><h2 id="установка-приложения" tabindex="-1">Установка приложения <a class="header-anchor" href="#установка-приложения" aria-label="Permalink to &quot;Установка приложения&quot;">​</a></h2><ol><li>Выберите приложение в <strong>Supermarket</strong> и откройте его страницу.</li><li>Нажмите <strong>Install to Bot</strong> и выберите целевой Bot.</li><li>Если приложение объявляет переменные окружения, сначала заполните требуемые значения.</li><li>Подтвердите установку.</li></ol><p>Для установки и обновления рабочее пространство Bot должно быть запущено: навыки записываются в рабочее пространство, зависимости устанавливаются в него, коннекторы привязываются. Установка показывает прогресс; прерванную установку можно <strong>продолжить</strong> или <strong>восстановить</strong>.</p><hr><h2 id="после-установки-вкладка-apps-у-bot" tabindex="-1">После установки: вкладка Apps у Bot <a class="header-anchor" href="#после-установки-вкладка-apps-у-bot" aria-label="Permalink to &quot;После установки: вкладка Apps у Bot&quot;">​</a></h2><p>Вкладка <strong>Apps</strong> на странице Bot перечисляет установленные приложения с состоянием каждого компонента:</p><table tabindex="0"><thead><tr><th>Компонент</th><th>Куда попадает</th></tr></thead><tbody><tr><td><strong>Навыки</strong></td><td>Записываются в управляемый каталог рабочего пространства <code>/data/skills/&lt;registry&gt;/&lt;app&gt;/</code>; ими владеет приложение — они обновляются и удаляются вместе с ним, так что не редактируйте их вручную (см. <a href="./skills.html">Навыки</a>)</td></tr><tr><td><strong>Зависимости</strong></td><td>Устанавливаются в рабочее пространство Bot и используются совместно с другими приложениями этого же рабочего пространства, которым они нужны</td></tr><tr><td><strong>Коннекторы</strong></td><td>Помечаются как <strong>Needs authorization</strong>, <strong>Optional</strong> или <strong>Shared across workspaces</strong>; нажмите <strong>Authorize</strong>, чтобы пройти OAuth или ввести API-ключ (см. <a href="./../self-hosted/connectors.html">Коннекторы</a>)</td></tr></tbody></table><p>Частые действия: <strong>Check for updates</strong>, <strong>Update</strong>, <strong>Remove</strong>. Если часть компонентов завершилась с ошибкой или ещё ждёт авторизации, приложение помечается как требующее внимания — откройте список его компонентов и завершите настройку.</p><hr><h2 id="откуда-берется-каталог" tabindex="-1">Откуда берётся каталог <a class="header-anchor" href="#откуда-берется-каталог" aria-label="Permalink to &quot;Откуда берётся каталог&quot;">​</a></h2><p>Содержимое Supermarket отдаётся из вышестоящего реестра, по умолчанию <code>supermarket.memoh.ai</code>. В самостоятельно развёрнутых инстансах можно указать в <code>supermarket.base_url</code> другой доверенный каталог; см. справочник по конфигурации в <a href="./../self-hosted/docker.html">Server Deploy</a>.</p><hr><h2 id="как-внести-вклад" tabindex="-1">Как внести вклад <a class="header-anchor" href="#как-внести-вклад" aria-label="Permalink to &quot;Как внести вклад&quot;">​</a></h2><p>Новые приложения можно отправлять в:</p><ul><li><a href="https://github.com/felinics/supermarket" target="_blank" rel="noreferrer">felinics/supermarket</a></li></ul>',19)])])}const m=r(s,[["render",n]]);export{u as __pageData,m as default};
